from pathlib import Path
import tarfile,tomllib,yaml
kit=Path.cwd()
with tarfile.open('../coding-standards-c12-pass2-frozen-public-inputs.tar.gz') as tf:
 for name in ['.gitleaks.toml','.github/workflows/security.yml']:
  old=tf.extractfile(name).read();new=(kit/name).read_bytes();assert old==new+b'\n'
  if name.endswith('toml'):assert tomllib.loads(old.decode())==tomllib.loads(new.decode())
  else:assert yaml.safe_load(old)==yaml.safe_load(new)
print('Only one terminal newline per file removed; YAML/TOML parsed objects identical.')
